/// The compile-time assertions of the hand-written items: one per item of
/// `GUEST_HAND` and per method of each extension trait, binding the item
/// written in `src/guest/hand/` to the signature the type mapping derives
/// from the api, so that a hand-written item that is missing or whose types
/// drifted fails the build.
#[allow(dead_code, clippy::type_complexity, reason = "the assertions are checked when the crate compiles, nothing calls them, and each writes a whole signature")]
mod assertions {
    use std::sync::Arc;

    use crate::guest::generated::prelude::*;
    use crate::guest::model::element::Aspect;
    use crate::guest::core::registry::BackendDef;
    use crate::guest::lang::BuiltLang;
    use crate::guest::stdcore::features::citations::CitationProvider;
    use crate::guest::stdcore::features::citations::CitationRequest;
    use crate::guest::stdcore::features::citations::CitationResult;
    use crate::guest::model::aspects::ContentRef;
    use crate::guest::core::registry::Contributed;
    use crate::guest::core::lowering::DefaultMark;
    use crate::guest::lang::mint::ElementDef;
    use crate::guest::model::element::ElementSpec;
    use crate::guest::lang::rewrites::userdefs::Expand;
    use crate::guest::lang::rewrites::userdefs::ExpandCx;
    use crate::guest::lang::rewrites::userdefs::ExpandPolicy;
    use crate::guest::lang::rewrites::userdefs::Expander;
    use crate::guest::lang::rewrites::userdefs::Expansion;
    use crate::guest::core::registry::FeatureBuilder;
    use crate::guest::core::registry::Finalizer;
    use crate::guest::lang::FlmDiagnostics;
    use crate::guest::core::registry::LateInit;
    use crate::guest::core::lowering::Lower;
    use crate::guest::core::lowering::LowerCx;
    use crate::guest::core::lowering::Lowerer;
    use crate::guest::core::lowering::Lowering;
    use crate::guest::core::lowering::LoweringDecl;
    use crate::guest::core::lowering::LoweringRule;
    use crate::guest::core::stage::Needs;
    use crate::guest::techy::node::Node;
    use crate::guest::stdcore::features::citations::ProviderCx;
    use crate::guest::model::aspects::RefPoint;
    use crate::guest::model::aspects::Referenceable;
    use crate::guest::techy::transform::Restage;
    use crate::guest::techy::transform::Restager;
    use crate::guest::core::run::RewriteCx;
    use crate::guest::core::stage::RewriteDecl;
    use crate::guest::core::stage::RewriteStage;
    use crate::guest::model::aspects::Sectioning;
    use crate::guest::core::stage::Stage;
    use crate::guest::core::run::StageCx;
    use crate::guest::core::stage::StageDecl;
    use crate::guest::core::data::store::StageOut;
    use crate::guest::stdcore::features::compose::TemplateContext;
    use crate::guest::stdcore::features::compose::TemplateCx;
    use crate::guest::stdcore::features::compose::TemplateDescription;
    use crate::guest::stdcore::features::compose::TemplateFile;
    use crate::guest::stdcore::features::compose::TemplateModule;
    use crate::guest::lang::rewrites::userdefs::UserDefinition;

    /// The record-and-lend items (`GUEST_HAND`).
    fn hand_written() {
        let _: fn(&FeatureBuilder) -> Result<String, ExtError> = FeatureBuilder::feature;
        let _: fn(&mut FeatureBuilder, Arc<dyn Stage>) -> Result<(), ExtError> = FeatureBuilder::stage;
        let _: fn(&mut FeatureBuilder, Arc<dyn RewriteStage>) -> Result<(), ExtError> = FeatureBuilder::rewrite_stage;
        let _: fn(&mut FeatureBuilder, BackendDef) -> Result<(), ExtError> = FeatureBuilder::backend;
        let _: fn(&mut FeatureBuilder, &str, Contributed) -> Result<(), ExtError> = FeatureBuilder::contribute_to;
        let _: fn(&mut FeatureBuilder, &str, Contributed) -> Result<(), ExtError> = FeatureBuilder::contribute_first_to;
        let _: fn(&mut FeatureBuilder, &str, Contributed) -> Result<(), ExtError> = FeatureBuilder::peer_slot;
        let _: fn(&mut FeatureBuilder, &str, Aspect) -> Result<(), ExtError> = FeatureBuilder::attach;
        let _: fn(&mut FeatureBuilder, Arc<dyn LateInit>) -> Result<(), ExtError> = FeatureBuilder::late_init;
        let _: fn(&mut FeatureBuilder, Arc<dyn Finalizer>) -> Result<(), ExtError> = FeatureBuilder::finalizer;
        let _: fn(ElementSpec, Aspect) -> Result<ElementSpec, ExtError> = ElementSpec::with;
        let _: fn(&UserDefinition, &str, &str, Arc<dyn Expand>) -> Result<ElementDef, ExtError> = UserDefinition::element_def_with;
        let _: fn(String, String, LoweringDecl, Arc<dyn Lower>, DefaultMark) -> Result<LoweringRule, ExtError> = LoweringRule::new;
    }

    /// The methods of `Lower`, on any type implementing it.
    fn lower_methods<T: Lower + ?Sized>() {
        let _: fn(&T, &Node, &mut LowerCx, &mut Lowerer) -> Result<Lowering, ExtError> = T::lower;
    }

    /// The methods of `LateInit`, on any type implementing it.
    fn late_init_methods<T: LateInit + ?Sized>() {
        let _: fn(&T, &BuiltLang, &mut FlmDiagnostics) -> Result<(), ExtError> = T::late_init;
    }

    /// The methods of `Finalizer`, on any type implementing it.
    fn finalizer_methods<T: Finalizer + ?Sized>() {
        let _: fn(&T, &mut FeatureBuilder) -> Result<(), ExtError> = T::finalize;
    }

    /// The methods of `Stage`, on any type implementing it.
    fn stage_methods<T: Stage + ?Sized>() {
        let _: fn(&T) -> StageDecl = T::decl;
        let _: fn(&T) -> Needs = T::needs;
        let _: fn(&T, &StageCx, &mut StageOut) -> Result<(), ExtError> = T::run;
    }

    /// The methods of `RewriteStage`, on any type implementing it.
    fn rewrite_stage_methods<T: RewriteStage + ?Sized>() {
        let _: fn(&T) -> RewriteDecl = T::decl;
        let _: fn(&T) -> Needs = T::needs;
        let _: fn(&T, &Node, &RewriteCx, &mut Restager) -> Result<Restage, ExtError> = T::restage;
    }

    /// The methods of `Expand`, on any type implementing it.
    fn expand_methods<T: Expand + ?Sized>() {
        let _: fn(&T) -> ExpandPolicy = T::policy;
        let _: fn(&T, &Node, &mut ExpandCx, &mut Expander) -> Result<Expansion, ExtError> = T::expand;
    }

    /// The methods of `Referenceable`, on any type implementing it.
    fn referenceable_methods<T: Referenceable + ?Sized>() {
        let _: fn(&T, &Node) -> Result<Vec<RefPoint>, ExtError> = T::points;
    }

    /// The methods of `Sectioning`, on any type implementing it.
    fn sectioning_methods<T: Sectioning + ?Sized>() {
        let _: fn(&T, &Node) -> Result<u32, ExtError> = T::level;
        let _: fn(&T, &Node) -> Result<bool, ExtError> = T::in_toc;
        let _: fn(&T, &Node) -> Result<Option<ContentRef>, ExtError> = T::toc_title;
    }

    /// The methods of `CitationProvider`, on any type implementing it.
    fn citation_provider_methods<T: CitationProvider + ?Sized>() {
        let _: fn(&T) -> String = T::name;
        let _: fn(&T, &CitationRequest, &ProviderCx) -> Result<CitationResult, ExtError> = T::answer;
        let _: fn(&T, &[CitationRequest], &ProviderCx) -> Result<Vec<CitationResult>, ExtError> = T::answer_all;
    }

    /// The methods of `TemplateModule`, on any type implementing it.
    fn template_module_methods<T: TemplateModule + ?Sized>() {
        let _: fn(&T) -> String = T::name;
        let _: fn(&T, &Value) -> Result<TemplateDescription, ExtError> = T::describe;
        let _: fn(&T, &TemplateContext, &TemplateCx) -> Result<Vec<TemplateFile>, ExtError> = T::files;
        let _: fn(&T, &TemplateContext, &TemplateCx) -> Result<String, ExtError> = T::render;
    }
}
